  const ENZ = "3.1.3.2", PROT = "3.1.1.4", MEM = "3.1.4.1", TRX = "3.1.8.2";
  const TBL = (head, rows, cap) => `<table class="tbl cl-data">${cap ? `<caption>${cap}</caption>` : ""}<thead><tr>${head.map((x) => `<th scope="col">${x}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((x, i) => (i === 0 ? `<th scope="row">${x}</th>` : `<td>${x}</td>`)).join("")}</tr>`).join("")}</tbody></table>`;
  // Case-study intro tables use the stacked layout of .cl-table: a normal table on wide screens; below 760 px each row
