  let capN = 0;
  const TBLS = (head, rows, cap) => { const cid = cap ? `cl-cap-24-${++capN}` : ""; return `${cap ? `<p class="small muted" id="${cid}">${cap}</p>` : ""}<table class="tbl cl-table cl-stack"${cap ? ` aria-describedby="${cid}"` : ""}><thead><tr>${head.map((x) => `<th scope="col">${x}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((x, i) => (i === 0 ? `<td data-h="${head[0]}"><strong>${x}</strong></td>` : `<td data-h="${head[i]}">${x}</td>`)).join("")}</tr>`).join("")}</tbody></table>`; };

